mapper.sql:
FROM t_party p JOIN t_party_profile f ON f.party_id=p.party_id AND f.current_slot=1 JOIN t_individual_profile i ON i.profile_id=f.profile_id
WHERE p.party_type='INDIVIDUAL' AND (f.draft_application_id=#{application.applicationId}
  OR (f.approved_time IS NOT NULL AND EXISTS(SELECT 1 FROM t_party_relation r
    WHERE r.related_party_id=p.party_id AND r.organization_party_id=#{application.partyId}
      AND r.client_application_id=#{application.applicationId})))
